view.source:
{{define "memory-page"}}
<section class="observability memory-page" id="memory-page">
{{with .Memory}}{{if or .Selected .MaintenanceSelected}}
<a class="back-link" href="{{memoryURL .Query "ref" ""}}">{{tr "← Memory"}}</a>
<div id="memory-workbench">{{template "memory-workbench" $}}</div>
{{else}}
<form class="obs-filters" data-auto-filter id="memory-filters" method="get" action="/developer/memory" aria-label="{{tr "Filter memories"}}">
{{if .Presentation}}<input type="hidden" name="inspector_revision" value="{{.Presentation.ReaderRevision}}">{{end}}
{{if .Query.Layer}}<input type="hidden" name="layer" value="{{.Query.Layer}}">{{end}}
<div class="obs-list-heading control-list-heading"><h1>{{tr "Memory"}}</h1></div>
{{if ne .Query.View "maintenance"}}<div class="control-search obs-search control-list-search">{{template "icon-search"}}<input type="search" name="search" value="{{.Query.Search}}" maxlength="200" placeholder="{{tr "Search memory content or ID…"}}" aria-label="{{tr "Search memories"}}"><button type="submit" class="control-icon-button" aria-label="{{tr "Search memories"}}">{{template "icon-arrow-right"}}</button></div>{{end}}
<div class="control-list-toolbar obs-table-toolbar memory-list-toolbar">{{if ne .Query.View "maintenance"}}<button type="button" class="secondary control-toolbar-button" data-list-filter-toggle="memory-filter-rail" hidden>{{template "icon-filter"}}<span>{{tr "Filters"}}</span></button>{{end}}<nav class="section-tabs compact" aria-label="{{tr "Memory views"}}"><a href="{{memoryURL .Query "layer" "transcripts"}}" {{if eq .Query.Layer "transcripts"}}aria-current="page"{{end}}>{{tr "Transcripts"}}</a><a href="{{memoryURL .Query "layer" "notes"}}" {{if and (ne .Query.View "maintenance") (or (not .Query.Layer) (eq .Query.Layer "notes"))}}aria-current="page"{{end}}>{{tr "Memory notes"}}</a><a href="{{memoryURL .Query "layer" "representations"}}" {{if eq .Query.Layer "representations"}}aria-current="page"{{end}}>{{tr "Memory representations"}}</a><a href="{{memoryURL .Query "layer" "injected"}}" {{if eq .Query.Layer "injected"}}aria-current="page"{{end}}>{{tr "Injected context"}}</a><a href="{{memoryURL .Query "view" "maintenance"}}" {{if eq .Query.View "maintenance"}}aria-current="page"{{end}}>{{tr "Maintenance records"}}</a></nav></div>
{{if eq .Query.View "maintenance"}}
<div class="obs-results-main memory-maintenance"><section class="obs-trace-list memory-record-list"><div class="obs-table-scroll" tabindex="0" role="region" aria-label="{{tr "Maintenance records"}}"><table class="control-list-table"><colgroup><col class="obs-col-id"><col class="obs-col-created"><col class="memory-col-operation"><col class="memory-col-status"><col class="memory-col-attempts"><col class="memory-col-error"><col class="memory-col-execution"><col class="memory-col-attempts"><col class="obs-col-tokens"><col class="obs-col-cost"></colgroup><thead><tr><th>{{tr "Receipt"}}</th><th>{{tr "Created time"}}</th><th>{{tr "Operation"}}</th><th>{{tr "Status"}}</th><th>{{tr "Attempts"}}</th><th>{{tr "Error code"}}</th><th>{{tr "Source execution"}}</th><th>{{tr "Generations"}}</th><th>{{tr "Tokens"}}</th><th>{{tr "Model cost"}}</th></tr></thead><tbody>{{range .Page.Maintenance}}<tr data-memory-ref="{{.Ref}}"><td>{{template "identifier" (identifier "" .Ref "")}}</td><td>{{traceTime (.CreatedAt.Format "2006-01-02T15:04:05Z07:00")}}</td><td><a class="memory-open" href="{{memoryURL $.Memory.Query "ref" .Ref}}">{{tr .Operation}}</a></td><td><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span></td><td>{{.Attempts}}</td><td>{{if .Error}}<span class="obs-cell-text" title="{{.Error}}">{{.Error}}</span>{{else}}—{{end}}</td><td>{{if .RunID}}<a href="/developer/observability?run={{.RunID}}">{{tr "Open trace →"}}</a>{{else}}—{{end}}</td><td>{{with .Metrics}}{{.Generations}}{{else}}—{{end}}</td><td>{{with .Metrics}}{{if .KnownUsageGenerations}}{{.InputTokens}} / {{.OutputTokens}}{{else}}—{{end}}{{else}}—{{end}}</td><td>{{template "memory-maintenance-cost" .Metrics}}</td></tr>{{else}}<tr><td colspan="10"><div class="empty-state"><h2>{{tr "No maintenance records"}}</h2></div></td></tr>{{end}}</tbody></table></div></section>
{{else}}
<div class="obs-results-layout"><details id="memory-filter-rail" class="obs-filter-rail" open><summary>{{template "icon-filter"}}<span>{{tr "Filters"}}</span>{{template "icon-chevron"}}</summary><div class="obs-filter-rail-content">
{{if or (not .Query.Layer) (eq .Query.Layer "notes")}}<details class="obs-facet" open><summary>{{tr "Memory tier"}}</summary><fieldset><legend class="sr-only">{{tr "Memory tier"}}</legend><label><input type="radio" name="tier" value="" {{if not .Query.Tier}}checked{{end}}> {{tr "All tiers"}}</label><label><input type="radio" name="tier" value="core" {{if eq .Query.Tier "core"}}checked{{end}}> Core</label><label><input type="radio" name="tier" value="recall" {{if eq .Query.Tier "recall"}}checked{{end}}> Recall</label></fieldset></details>
{{end}}{{if ne .Query.Layer "transcripts"}}<details class="obs-facet" open><summary>{{tr "Formation"}}</summary><fieldset><legend class="sr-only">{{tr "Formation"}}</legend><label><input type="radio" name="origin" value="" {{if not .Query.Origin}}checked{{end}}> {{tr "All origins"}}</label><label><input type="radio" name="origin" value="automatic" {{if eq .Query.Origin "automatic"}}checked{{end}}> {{tr "Automatically extracted"}}</label><label><input type="radio" name="origin" value="explicit" {{if eq .Query.Origin "explicit"}}checked{{end}}> {{tr "Explicitly remembered"}}</label><label><input type="radio" name="origin" value="written" {{if eq .Query.Origin "written"}}checked{{end}}> {{tr "Written note"}}</label><label><input type="radio" name="origin" value="dream" {{if eq .Query.Origin "dream"}}checked{{end}}> {{tr "Dreaming"}}</label><label><input type="radio" name="origin" value="unknown" {{if eq .Query.Origin "unknown"}}checked{{end}}> {{tr "Unknown origin"}}</label></fieldset></details>
<details class="obs-facet" open><summary>{{tr "Status"}}</summary><fieldset><legend class="sr-only">{{tr "Status"}}</legend><label><input type="radio" name="status" value="active" {{if eq (memoryStatus .Query) "active"}}checked{{end}}> {{tr "active"}}</label><label><input type="radio" name="status" value="superseded" {{if eq .Query.Status "superseded"}}checked{{end}}> {{tr "superseded"}}</label><label><input type="radio" name="status" value="all" {{if eq .Query.Status "all"}}checked{{end}}> {{tr "All statuses"}}</label></fieldset></details>
{{end}}<details class="obs-facet"><summary>{{tr "Created time"}}</summary><div class="obs-filter-fields"><label>{{tr "Created after"}}<input type="datetime-local" name="since" data-local-input="{{if not .Query.Since.IsZero}}{{.Query.Since.Format "2006-01-02T15:04:05Z07:00"}}{{end}}" value="{{timeInput .Query.Since}}"></label><label>{{tr "Created before"}}<input type="datetime-local" name="until" data-local-input="{{if not .Query.Until.IsZero}}{{.Query.Until.Format "2006-01-02T15:04:05Z07:00"}}{{end}}" value="{{timeInput .Query.Until}}"></label></div></details>
<div class="obs-filter-actions"><button type="submit" data-filter-submit>{{tr "Apply filters"}}</button></div></div></details>
<div class="obs-results-main">
{{if or .Query.Search .Query.Tier .Query.Origin .Query.Status (not .Query.Since.IsZero) (not .Query.Until.IsZero)}}<div class="obs-active-filters"><span>{{tr "Filtered memories"}}</span><a href="/developer/memory">{{tr "Clear all"}}</a></div>{{end}}
<section class="obs-trace-list memory-record-list"><div class="obs-table-scroll" tabindex="0" role="region" aria-label="{{tr "Memory results"}}"><table class="control-list-table"><colgroup><col class="memory-col-content"><col class="memory-col-tier"><col class="memory-col-origin"><col class="memory-col-status"><col class="memory-col-sources"><col class="memory-col-created"></colgroup><thead><tr><th>{{tr "Memory content"}}</th><th>{{tr "Memory layer"}}</th><th>{{tr "Formation"}}</th><th>{{tr "Status"}}</th><th>{{tr "Sources"}}</th><th>{{tr "Created time"}}</th></tr></thead><tbody>
{{range .Page.Items}}<tr data-memory-ref="{{.Ref}}"><td><a class="memory-open obs-cell-text" href="{{memoryURL $.Memory.Query "ref" .Ref}}" title="{{if eq .ContentState "available"}}{{.Content}}{{else}}{{.Ref}}{{end}}">{{if eq .ContentState "available"}}{{if and .Title (ne .Layer "transcripts")}}{{.Title}}{{else}}{{.Content}}{{end}}{{else if eq .ContentState "retired"}}{{tr "Superseded memory"}}{{else}}{{tr "Memory content unavailable"}}{{end}}</a></td><td><span class="control-kind-badge" data-kind="{{if eq .Tier "core"}}generation{{else}}agent{{end}}">{{tr (memoryLayerLabel .Layer)}}</span></td><td>{{tr (memoryOriginLabel .Origin)}}</td><td><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span></td><td>{{if .Sources}}{{.SourceCount}} · {{tr (memorySourceLabel (index .Sources 0).Kind)}}{{else}}<span class="muted">{{tr "Source unavailable"}}</span>{{end}}</td><td>{{traceTime (.CreatedAt.Format "2006-01-02T15:04:05Z07:00")}}</td></tr>
{{else}}<tr><td colspan="6"><div class="empty-state"><h2>{{tr "No matching memories"}}</h2><p>{{tr "Memories formed from conversations or explicit remember requests will appear here."}}</p>{{if or .Query.Search .Query.Tier .Query.Origin .Query.Status (not .Query.Since.IsZero) (not .Query.Until.IsZero)}}<a href="/developer/memory">{{tr "Clear all"}}</a>{{end}}</div></td></tr>{{end}}
</tbody></table></div></section>
{{end}}
<div class="obs-list-footer control-list-footer"><span>{{tr "Total"}}: {{.Page.Total}} · {{if eq .Query.View "maintenance"}}{{len .Page.Maintenance}}{{else}}{{len .Page.Items}}{{end}} {{tr "records on this page"}}</span>{{if .Page.Next}}<a class="button secondary" href="{{memoryURL .Query "cursor" .Page.Next}}">{{tr "Older records →"}}</a>{{end}}</div></div>{{if ne .Query.View "maintenance"}}</div>{{end}}
</form>
{{end}}{{end}}
</section>
{{end}}

{{define "memory-workbench"}}{{if .Memory.MaintenanceSelected}}{{template "memory-maintenance-detail" .}}{{else}}{{template "memory-document-detail" .}}{{end}}{{end}}

{{define "memory-document-detail"}}{{with .Memory}}{{with .Selected}}
<div class="obs-workbench memory-workbench" data-split-view data-split-storage="steward.memory.sources-ratio.v1" data-memory-id="{{.Ref}}">
<section class="obs-tree-pane memory-sources" aria-label="{{tr "Memory sources"}}"><div class="obs-pane-heading"><h2>{{tr "Sources"}}</h2><span>{{.SourceCount}}</span></div><div class="memory-source-list">{{range .Sources}}<div class="memory-source" data-source-kind="{{.Kind}}">{{if or (eq .Kind "conversation") (eq .Kind "task")}}<a class="memory-select" href="{{memoryURL $.Memory.Query "source" .Ref}}" {{if eq $.Memory.Query.Source .Ref}}aria-current="true"{{end}}>{{template "icon-source"}}<span><strong>{{tr (memorySourceLabel .Kind)}}</strong></span></a>{{else}}<div class="memory-source-label">{{template "icon-source"}}<span><strong>{{tr (memorySourceLabel .Kind)}}</strong></span></div>{{end}}{{template "identifier" (identifier "" .Ref "")}}{{if .RunID}}<a class="text-link" href="/developer/observability?run={{.RunID}}">{{tr "Open trace →"}}</a>{{end}}{{if eq .Kind "task"}}<a class="text-link" href="{{taskURL .Ref}}">{{tr "Open task →"}}</a>{{end}}</div>{{else}}<p class="muted">{{tr "Source unavailable"}}</p>{{end}}</div>{{if .NextSourcesOffset}}<a class="memory-select text-link" href="{{memoryURL $.Memory.Query "sources_after" (memorySourcesOffset .NextSourcesOffset)}}">{{tr "More sources →"}}</a>{{end}}
{{if .Related}}<div class="memory-lineage"><h3>{{tr "Related memories"}}</h3>{{range .Related}}<a class="memory-select" href="{{memoryURL $.Memory.Query "ref" .Ref}}" title="{{.Ref}}">{{.Title}}</a>{{end}}</div>{{end}}
{{if or .Supersedes .ReplacedBy}}<div class="memory-lineage"><h3>{{tr "Replacement history"}}</h3>{{if .Supersedes}}<a class="memory-select" href="{{memoryURL $.Memory.Query "ref" .Supersedes}}">{{tr "Replaces"}}<small>{{.Supersedes}}</small></a>{{end}}{{if .ReplacedBy}}<a class="memory-select" href="{{memoryURL $.Memory.Query "ref" .ReplacedBy}}">{{tr "Replaced by"}}<small>{{.ReplacedBy}}</small></a>{{end}}</div>{{end}}</section>
<section class="obs-detail-pane memory-detail" aria-label="{{tr "Memory details"}}"><header class="obs-node-header"><div class="obs-selected-heading"><span class="obs-selected-icon" data-kind="{{if eq .Tier "core"}}generation{{else}}agent{{end}}">{{template "icon-memory"}}</span><h2 class="obs-selected-name">{{if .Title}}{{.Title}}{{else}}{{tr "Memory"}}{{end}}</h2><span class="control-kind-badge" data-kind="{{if eq .Tier "core"}}generation{{else}}agent{{end}}">{{tr (memoryLayerLabel .Layer)}}</span></div><span class="obs-started-time">{{localTime (.CreatedAt.Format "2006-01-02T15:04:05.000Z07:00") "datetime"}}</span><div class="obs-node-facts"><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span><span class="control-metric-badge">{{tr (memoryOriginLabel .Origin)}}</span></div></header>
<div class="obs-detail-toolbar"><nav class="obs-detail-tabs" aria-label="{{tr "Memory detail sections"}}"><span class="memory-preview-tab">{{tr "Preview"}}</span></nav></div>
<section class="memory-content-section"><h3>{{tr "Memory content"}}</h3>{{if eq .ContentState "available"}}<div class="memory-content" data-memory-content>{{.Content}}</div>{{else if eq .ContentState "retired"}}<p class="muted">{{tr "This memory has been superseded. Only its metadata is available."}}</p>{{else}}<p class="muted">{{tr "Memory content could not be decrypted. Check the memory key configuration and refresh."}}</p>{{end}}</section>
{{range .Sources}}{{if eq $.Memory.Query.Source .Ref}}<section class="memory-content-section memory-source-content"><h3>{{tr "Source content"}}</h3><p class="muted memory-source-reference">{{template "identifier" (identifier "" .Ref "")}}</p><div class="memory-content" data-memory-source-content>{{.Text}}</div>{{if .NextOffset}}<a class="memory-select text-link" href="{{memoryURL $.Memory.Query "offset" (memoryOffset .NextOffset)}}">{{tr "Continue reading →"}}</a>{{end}}</section>{{end}}{{end}}
<details class="technical-details memory-metadata"><summary>{{tr "Metadata"}}</summary><dl><dt>{{tr "Memory ID"}}</dt><dd>{{template "identifier" (identifier "" .Ref "")}}</dd><dt>{{tr "Sources"}}</dt><dd>{{.SourceCount}}</dd>{{if .Revision}}<dt>{{tr "Revision"}}</dt><dd>{{.Revision}}</dd>{{end}}{{if and .Tier (eq .Layer "notes")}}<dt>{{tr "Memory tier"}}</dt><dd>{{.Tier}}</dd>{{end}}</dl></details>
</section></div>
{{end}}{{end}}{{end}}


{{define "memory-maintenance-cost"}}{{with .}}{{range .Costs}}<span class="obs-cost">{{.Currency}} {{money .ReferenceMicros}}</span>{{else}}<span class="muted">{{tr "Not priced"}}</span>{{end}}{{else}}—{{end}}{{end}}

{{define "memory-maintenance-detail"}}{{with .Memory.MaintenanceSelected}}
<div class="obs-workbench memory-workbench" data-memory-id="{{.Ref}}"><section class="obs-detail-pane">
<header class="obs-detail-header"><h2>{{tr .Operation}}</h2><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span></header>
<div class="obs-metrics"><div><small>{{tr "Created time"}}</small><strong>{{traceTime (.CreatedAt.Format "2006-01-02T15:04:05Z07:00")}}</strong></div><div><small>{{tr "Attempts"}}</small><strong>{{.Attempts}}</strong></div>{{if .Error}}<div><small>{{tr "Error code"}}</small><strong>{{.Error}}</strong></div>{{end}}</div>
{{with .Metrics}}<div class="obs-metrics"><div><small>{{tr "Generations"}}</small><strong>{{.Generations}}</strong></div><div><small>{{tr "Input / output tokens"}}</small><strong>{{if .KnownUsageGenerations}}{{.InputTokens}} / {{.OutputTokens}}{{else}}—{{end}}</strong></div><div><small>{{tr "Cache read tokens"}}</small><strong>{{if .KnownUsageGenerations}}{{.CacheReadTokens}}{{else}}—{{end}}</strong></div><div><small>{{tr "Model cost"}} {{template "help" (help "memory-maintenance-cost-help" (tr "Model cost") (tr "Reference API price estimate, not an invoice. Subscription charges may differ."))}}</small><strong>{{template "memory-maintenance-cost" .}}</strong></div><div><small>{{tr "Documents written"}}</small><strong>{{.DocumentsWritten}}</strong></div><div><small>{{tr "Documents retired"}}</small><strong>{{.DocumentsRetired}}</strong></div><div><small>{{tr "Unchanged writes"}}</small><strong>{{.UnchangedWrites}}</strong></div><div><small>{{tr "Later reads"}}</small><strong>{{.LaterToolReads}}</strong></div><div><small>{{tr "Later injections"}}</small><strong>{{.LaterInjections}}</strong></div></div>{{end}}
<section class="memory-generation-history"><h3>{{tr "Model attempts"}}</h3><p class="obs-detail-note">{{tr "Latest 50 attempts. Failed proposals never become memory; retry success replaces the current error."}}</p>{{range .Generations}}<details class="technical-details"><summary>{{tr .Purpose}} · {{tr .Status}} · {{traceTime (.CreatedAt.Format "2006-01-02T15:04:05Z07:00")}}</summary><dl class="obs-detail-properties"><div><dt>{{tr "Model"}}</dt><dd>{{if .Model}}{{.Model}}{{else}}—{{end}}</dd></div><div><dt>{{tr "Latency"}}</dt><dd>{{milliseconds .LatencyMS}}</dd></div><div><dt>{{tr "Input tokens"}}</dt><dd>{{if ne .InputTokens nil}}{{.InputTokens}}{{else}}—{{end}}</dd></div><div><dt>{{tr "Output tokens"}}</dt><dd>{{if ne .OutputTokens nil}}{{.OutputTokens}}{{else}}—{{end}}</dd></div></dl>{{if eq .Status "failed"}}<p class="feedback error">{{if .Failure}}{{tr .Failure}}{{else}}{{tr "Failure details were not recorded for this older attempt."}}{{end}}</p>{{end}}{{template "identifier" (identifier "ID" .ID "")}}</details>{{else}}<p class="obs-empty">{{tr "No model attempts recorded."}}</p>{{end}}</section>
{{template "identifier" (identifier "Receipt" .Ref "")}}{{if .RunID}}<a class="text-link" href="/developer/observability?run={{.RunID}}">{{tr "Open trace →"}}</a>{{end}}
</section></div>
{{end}}{{end}}

stylesheet.source:
/* Memory composes the same compact list, filter rail, split panes and sheet as Traces. */
.memory-page .obs-list-heading{justify-content:space-between;gap:12px}
.memory-list-toolbar{justify-content:flex-start;min-height:48px}
.memory-list-toolbar .section-tabs{margin:0;border:0;gap:16px;min-width:0;max-width:100%}.memory-list-toolbar .section-tabs a{padding:6px 0;border-radius:0;font-size:12px}
.memory-record-list table{min-width:1200px}.memory-col-content{width:360px}.memory-col-tier{width:185px}.memory-col-origin{width:160px}.memory-col-status{width:105px}.memory-col-sources{width:190px}.memory-col-created{width:170px}
.memory-maintenance{min-height:calc(100dvh - 152px)}
.memory-open{text-decoration:none}.memory-open:hover{text-decoration:underline}.memory-workbench .obs-tree-pane,.memory-workbench .obs-detail-pane{max-height:none}
.memory-preview-tab{font-size:12px;font-weight:600;padding-bottom:8px;border-bottom:2px solid var(--foreground)}
.memory-source-list{display:grid;gap:4px;padding-top:8px}.memory-source{min-width:0;padding:4px 0}.memory-source>a.memory-select,.memory-source-label{display:flex;align-items:flex-start;gap:8px;min-width:0;padding:8px;border-radius:6px;text-decoration:none}
.memory-source>a.memory-select:hover{background:var(--hover)}.memory-source>a[aria-current]{background:color-mix(in srgb,var(--trace-agent) 10%,var(--card))}.memory-source svg{width:15px;height:15px;flex:none;color:var(--trace-agent)}.memory-source span{min-width:0}.memory-source strong{font-size:12px;font-weight:500;display:block}.memory-source small{display:block;font-size:11px;color:var(--muted-foreground);overflow-wrap:anywhere;margin-top:3px}.memory-source>.text-link{font-size:11px;margin-left:31px;color:var(--trace-agent)}
.memory-content{font-size:13px;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.memory-content-section{margin-bottom:24px}.memory-content-section h3{font-size:12px}.memory-source-content{padding-top:12px;border-top:1px solid var(--border)}.memory-source-reference{font-size:11px;overflow-wrap:anywhere}
.memory-lineage{margin-top:24px;padding-top:12px;border-top:1px solid var(--border)}.memory-lineage h3{font-size:12px}.memory-lineage a{font-size:12px;display:block;padding:8px 0;overflow-wrap:anywhere}.memory-lineage small{display:block;overflow-wrap:anywhere;font-size:11px;color:var(--muted-foreground)}
.memory-metadata{padding-top:12px;border-top:1px solid var(--border);font-size:12px}.memory-metadata dl{display:grid;gap:6px}.memory-metadata dt{color:var(--muted-foreground)}.memory-metadata dd{margin:0;overflow-wrap:anywhere}
.control-sheet #memory-workbench{height:100%;display:flex;flex-direction:column;min-height:0}.control-sheet #memory-workbench>.memory-workbench{flex:1;min-height:0}.memory-page>#memory-workbench{height:calc(100dvh - 96px)}.memory-page>#memory-workbench>.obs-workbench{height:100%;min-height:0}
@container inspection-layout (max-width:700px){.memory-page>#memory-workbench{height:auto}.memory-page .memory-workbench{display:block}.memory-page .memory-sources{max-height:240px;height:auto}}
@media(max-width:760px){.memory-list-toolbar{padding-left:12px}.memory-source>a.memory-select{min-height:44px}.control-sheet #memory-workbench{height:auto}.memory-content{font-size:14px}}

.memory-col-operation{width:110px}.memory-col-attempts{width:80px}.memory-col-error{width:210px}.memory-col-execution{width:130px}.memory-record-list tr[data-memory-ref]:hover{background:var(--hover)}
.memory-generation-history{margin-block:24px}.memory-generation-history h3{font-size:var(--text-ui)}

